import bundle from '../content-bundle/projects.json'
import type { Locale } from './locale'

// Generated by scripts/build-content-bundle.cjs from content/{en,es}/projects.json.
interface LocalizedFields {
  title?: string
  idea?: string
  budget?: string
  current_development?: string
  timeframe?: string
}

interface ProjectBundleItem {
  id: string
  locales: Partial<Record<Locale, LocalizedFields>>
}

export interface ProjectOption {
  id: string
  title: string
  idea: string
  budget: string
  current_development: string
  timeframe: string
}

const projects: ProjectBundleItem[] = bundle

function localize(item: ProjectBundleItem, locale: Locale): LocalizedFields {
  return item.locales[locale] ?? item.locales.en ?? Object.values(item.locales)[0] ?? {}
}

export function getAllProjects(locale: Locale): ProjectOption[] {
  return projects.map(item => {
    const fields = localize(item, locale)
    return {
      id: item.id,
      title: fields.title ?? '',
      idea: fields.idea ?? '',
      budget: fields.budget ?? '',
      current_development: fields.current_development ?? '',
      timeframe: fields.timeframe ?? '',
    }
  })
}
